import{_ as a,a as t,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 23 Which glasses?","description":"学习 ones 与复数选择，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 23 Which glasses?","description":"学习 ones 与复数选择，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 ones 与复数选择，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 22 Give me a ... Which one?","link":"/life/english/new-concept/book-1/unit-01/lesson-022"},"next":{"text":"第一册：英语初阶 · Lesson 24 Give me some ... Which ones?","link":"/life/english/new-concept/book-1/unit-01/lesson-024"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 22 Give me a ... Which one?","link":"/life/english/new-concept/book-1/unit-01/lesson-022"},"next":{"text":"第一册：英语初阶 · Lesson 24 Give me some ... Which ones?","link":"/life/english/new-concept/book-1/unit-01/lesson-024"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-023.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-023.md"}'),l={name:"life/english/new-concept/book-1/unit-01/lesson-023.md"};function o(i,e,r,h,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-23-which-glasses" tabindex="-1">第一册：英语初阶 · Lesson 23 Which glasses? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-23-which-glasses" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 23 Which glasses?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-024">配套课 Lesson 24</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从多件物品中挑选一组 本课要掌握ones 与复数选择，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>glass</td><td>/ɡlɑːs/</td><td>n.</td><td>玻璃杯</td><td>two glasses</td></tr><tr><td>plate</td><td>/pleɪt/</td><td>n.</td><td>盘子</td><td>clean plates</td></tr><tr><td>some</td><td>/sʌm/</td><td>限定词</td><td>一些</td><td>some cups</td></tr><tr><td>ones</td><td>/wʌnz/</td><td>pron.</td><td>一些（替代物）</td><td>the small ones</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>the clean ones — 替代复数物品</li><li>give us some — 给我们一些</li></ul><h2 id="语法讲解-ones-与复数选择" tabindex="-1">语法讲解：ones 与复数选择 <a class="header-anchor" href="#语法讲解-ones-与复数选择" aria-label="Permalink to &quot;语法讲解：ones 与复数选择&quot;">​</a></h2><p>ones 替代已提到的复数可数名词；the clean ones 指前文的一组干净物品。some 后可接复数可数名词，也可接不可数名词；本课先用 some plates 这样的复数对象。give us/them 中代词是宾格。which glasses 的中心词为复数，回答时不要退回单数 one。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Please give us the clean plates.</p></blockquote><p>请把干净的盘子给我们。</p><p>Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不能把复数 plates 替换为 one；some 后单数 plate 通常不表示“一些盘子”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Please give us the clean plates.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Please give us the clean plates. I want the small ones beside the sink.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“从多件物品中挑选一组”写两至三句，再读给同伴听。至少使用一次ones 与复数选择，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。 I 是主语，want 是谓语，the small ones 是宾语；ones 指已知的复数物品，beside the sink 补充位置。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 we/us：Give ___ some plates.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> us</p><p><strong>解析：</strong> 按本课规则判断：ones 替代已提到的复数可数名词；the clean ones 指前文的一组干净物品。some 后可接复数可数名词，也可接不可数名词；本课先用 some plates 这样的复数对象。give us/them 中代词是宾格。which glasses 的中心词为复数，回答时不要退回单数 one。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“请把干净的盘子给我们。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Please give us the clean plates.</p><p><strong>解析：</strong> Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：I want the small ones beside the sink.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我要水槽旁边小的那些。</p><p><strong>解析：</strong> I 是主语，want 是谓语，the small ones 是宾语；ones 指已知的复数物品，beside the sink 补充位置。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：ones 与复数选择。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-022">上一课</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-024">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
